# name: trial_index_drift
# description: Pearson correlation between trial_index and the yes response; the model has no time-on-task term so predicts ~0, and an observed value away from null_mean means people drift toward more (positive) or fewer (negative) yeses over the session.
def test_statistic(df):
    x = df["trial_index"].astype(float).to_numpy()
    y = df["rating"].astype(float).to_numpy()
    if x.std() == 0 or y.std() == 0:
        return 0.0
    return float(np.corrcoef(x, y)[0, 1])

# name: cell_disagreement
# description: Mean over (set, target) cells of p_hat*(1-p_hat), where p_hat is the cell's yes rate; observed below null_mean means humans agree more (more extreme, all-or-none generalization) than the model's graded posterior predicts, above means humans are more split.
def test_statistic(df):
    p = df.groupby(["number_set", "target"])["rating"].mean()
    return float((p * (1 - p)).mean())

# name: singleton_set_yes_rate
# description: Overall yes rate on trials whose set has a single example; observed above null_mean means people generalize more broadly from one example than the model's size-principle posterior, below means more narrowly.
def test_statistic(df):
    n = df["number_set"].astype(str).str.count(",") + 1
    m = n == 1
    if m.sum() == 0:
        return 0.0
    return float(df.loc[m, "rating"].mean())
